const r2 = x => Math.round(x*100)/100;

function bandPct(p){ // library Table 2, linear within band
  if (p < 150) return 0;
  if (p < 200) return 0 + (p-150)/50*2;
  if (p < 250) return 2 + (p-200)/50*2;
  if (p < 300) return 4 + (p-250)/50*2;
  if (p < 400) return 6 + (p-300)/100*2.5;
  return 8.5;
}
function cap(p){ if (p<200) return 750; if (p<300) return 1900; if (p<400) return 3150; return null; }

function scen(agi,label,months=6,slcsp=1690,enroll=1720,aptc=9900){
  const fpl = agi/31200*100;
  const app = bandPct(fpl);
  const contribAnn = agi*app/100;
  const contribMo = r2(contribAnn/12);
  const ptcMo = Math.min(enroll, r2(slcsp-contribMo));
  const ptcAnn = r2(ptcMo*months);
  const excess = r2(aptc-ptcAnn);
  const c = cap(fpl);
  const repay = excess>0 ? (c===null? excess : Math.min(excess,c)) : 0;
  console.log(`${label}: AGI=${agi} FPL%=${fpl.toFixed(4)} app%=${app.toFixed(6)} contribAnn=${contribAnn.toFixed(4)} contribMo=${contribMo} PTCmo=${ptcMo} PTCann=${ptcAnn} excess=${excess} cap=${c} repay=${repay}`);
  return {ptcAnn, repay, fpl, app, contribAnn, contribMo};
}

// MAINLINE
const wages = 68000+54000, interest = 400;
console.log("wages",wages,"fedWH",5120+3610,"nyWH",3842+2910);
const basis = 10000-2100+6400+9800-12000+4600-5200;
const scorpAllowed = Math.min(28000,basis), suspended = 28000-scorpAllowed;
console.log("basis",basis,"allowed",scorpAllowed,"suspended",suspended);
const rent=12*1500, exp=11900+7860+5140+2350+1150+800, dep=Math.round(270000/27.5);
const rentalLoss = rent-exp-dep;
console.log("rentalLoss",rentalLoss,"dep",dep,"exp",exp," 270000/27.5=",270000/27.5);
const magi = wages+interest-scorpAllowed;
const allow = Math.max(0, Math.min(25000, 25000-0.5*Math.max(0,magi-100000)));
const rentAllowed = Math.min(allow, -rentalLoss), carry = -rentalLoss-rentAllowed;
console.log("MAGI",magi,"allowance",allow,"rentAllowed",rentAllowed,"carry",carry);
const agi = wages+interest-scorpAllowed-rentAllowed, ti = agi-31500;
console.log("AGI",agi,"TI",ti);
const mid=(59850+59900)/2, tax=0.10*23850+0.12*(mid-23850);
console.log("midpoint check",tax,"(table row 6708)");
const m = scen(agi,"MAIN 8962");
console.log("exact annual contribution 5.7115% x 91350 =", (agi*0.057115).toFixed(4));
console.log("1255.21*6 =", r2(1255.21*6));
const totalTax = 6708-2200+m.repay;
console.log("line22",6708-2200,"totalTax",totalTax,"refund",8730-totalTax);
console.log("benefit line: 9900-1900 =",9900-1900);

// ALT1: carve-out fails (judgment §3)
const agi2 = wages+interest-scorpAllowed;
console.log("ALT1 AGI",agi2,"TI",agi2-31500);
scen(agi2,"ALT1 8962");

// ALT2: rejected full-28k (judgment §1)
console.log("ALT2 naive(stale allowance):", wages+interest-28000-19550, "TI", wages+interest-28000-19550-31500);
const magi3 = wages+interest-28000;
const allow3 = Math.max(0, Math.min(25000, 25000-0.5*Math.max(0,magi3-100000)));
const rentAllowed3 = Math.min(allow3,21018);
const agi3 = wages+interest-28000-rentAllowed3, ti3=agi3-31500;
console.log("ALT2 consistent: MAGI",magi3,"allow",allow3,"rentAllowed",rentAllowed3,"AGI",agi3,"TI",ti3);
scen(agi3,"ALT2 8962");

// misc
console.log("prorate:", Math.round(68000*181/365), Math.round(54000*181/365));
console.log("days:", (Date.UTC(2025,5,30)-Date.UTC(2025,0,1))/86400000+1, (Date.UTC(2025,6,3)-Date.UTC(2025,0,1))/86400000+1);

